samples.raw_completion:
// Full Adder: HA1, HA2, FA1 form a full adder chain. The final carry-out is
// routed to the cout port.
module FullAdder (
    input a,
    input b,
    input cin,
    output reg cout,
    output reg sum
);
    wire w1, w2, w3;
    HA HA1 (.a(a), .b(b), .s(w1), .c(w2));
    HA HA2 (.a(w1), .b(cin), .s(sum), .c(w3));
    FA FA1 (.a(a), .b(b), .cin(cin), .sum(sum), .cout(cout));
    assign cout = w3;
endmodule

